+func TestEveryAliasHasAThinkingBudgetVerdict(t *testing.T) {
+	for _, alias := range KnownModelAliases() {
+		resolved := ResolveModelAlias(alias, nil)
+		rejects := modelsRejectingThinkingBudget[resolved]
+		accepts := modelsAcceptingThinkingBudget[resolved]
+		switch {
+		case rejects && accepts:
+			t.Errorf("%s (-> %s) is in BOTH verdict maps", alias, resolved)
+		case !rejects && !accepts:
+			t.Errorf("%s (-> %s) has no thinking-budget verdict.\n"+
+				"\tAdd it to modelsRejectingThinkingBudget (400 on `thinking.budget_tokens`) or to\n"+
+				"\tmodelsAcceptingThinkingBudget. Defaulting is the unsafe direction: an unclassified\n"+
+				"\tmodel is treated as accepting, and the failure is a 400 on EVERY call for that agent.",
+				alias, resolved)
+		}
+	}
+	if len(KnownModelAliases()) == 0 {
+		t.Fatal("ModelAliases is empty — this parity test is watching nothing")
+	}
+}
+
+func TestAcceptsThinkingBudget(t *testing.T) {

+	"github.com/gqls/agentchassis/platform/aiservice"
+			_ = rootService // read below by the thinking arm and the ladder
+			if btValue, btFrom, _ := actions.ResolveStepBudget("budget_tokens", root, workflowStepCfg, runtimeStepCfg); btFrom != "" {
+				model := resolveStepModel(stepService, rootService)
+				if !aiservice.AcceptsThinkingBudget(model) {
+					report.Findings = append(report.Findings, budgetFinding{
+						Agent: agent.Type, Path: path, Kind: "thinking_unsupported",
+						Effective: btValue, From: btFrom,
+						Detail: fmt.Sprintf("declares budget_tokens=%d at %q against model %q, which REJECTS a manual "+
+							"thinking budget with a 400. anthropic.go emits thinking:{type:enabled,budget_tokens:N} "+
+							"whenever this key resolves to a positive number, so this fails EVERY call for this step, "+
+							"not one. Anthropic replaced the fixed budget with adaptive thinking; the key is still "+
+							"correct on 4.6 (deprecated) and REQUIRED on 4.5 and older, which is why the reader was "+
+							"not simply changed to drop it (bugs_open/257)", btValue, btFrom, model),
+					})
+				}
+			}
+
+func resolveStepModel(stepService, rootService map[string]interface{}) string {
+	for _, m := range []map[string]interface{}{stepService, rootService} {
+		if m == nil {
+			continue
+		}
+		if model, ok := m["model"].(string); ok && model != "" {
+			return model
+		}
+	}
+	return ""
+}
+

+func TestBudgetTokensAgainstARejectingModelIsFatal(t *testing.T) {
+	agent := budgetAgent(t,
+		map[string]interface{}{"ai_service": budgetService(16000.0)},
+		map[string]models.Step{
+			"write": {Action: "execute_llm_prompt", Config: map[string]interface{}{
+				"ai_service": map[string]interface{}{
+					"model": "claude-sonnet-5", "provider": "anthropic",
+					"max_tokens": 16000.0, "budget_tokens": 10000.0,
+				},
+			}},
+		})
+	report := budgetPlacementFindings([]liveAgent{agent})
+	if len(report.Findings) != 1 || report.Findings[0].Kind != "thinking_unsupported" {
+		t.Fatalf("findings = %+v, want exactly one thinking_unsupported — a budget_tokens "+
+			"declaration against claude-sonnet-5 is a 400 on every call for this step", report.Findings)
+	}
+	if report.Findings[0].Effective != 10000 {
+		t.Errorf("effective = %d, want the declared 10000", report.Findings[0].Effective)
+	}
+}
